WITH eventos AS (SELECT id_evento,nome_evento,data_final,url_resultado,url_wiclax FROM public.tb_evento_corridas WHERE pais='BR' AND data_final=DATE '2026-08-30' AND nome_evento ILIKE '%FLORIPA%'),base AS (SELECT e.*,r.id_resultado,r.modalidade,r.nome_categoria,r.percurso,r.tempo_total,r.tempo_bruto,r.pcd,r.concluinte,r.homologado,r.status_final FROM eventos e JOIN public.tb_resultados r USING(id_evento) WHERE r.percurso BETWEEN 42 AND 42.2),suspeitos AS (SELECT id_evento,id_resultado,modalidade,nome_categoria,percurso,tempo_total::text,tempo_bruto::text,pcd FROM base WHERE status_final=0 AND homologado AND concluinte AND pcd IS FALSE AND NOT(coalesce(modalidade,'') ~* '(CADEIR|DEFICI|ANDANTE|HAND|BIKE|GUIA|(^|[^A-Z0-9])(PCD|ACD|DI|DV|DA|DMAI|DMS|CAD)([^A-Z0-9]|$))') AND tempo_total<TIME '02:00:00' AND tempo_total>TIME '00:00:00') SELECT jsonb_build_object('coletado_em',current_timestamp,'eventos',(SELECT jsonb_agg(to_jsonb(eventos)) FROM eventos),'suspeitos',(SELECT jsonb_agg(to_jsonb(suspeitos) ORDER BY tempo_total) FROM suspeitos),'aviso','Tempo abaixo de duas horas é sinal de auditoria, não prova da causa. Nenhum resultado foi alterado; nomes e nascimento não exportados.') AS payload